(function () { "use strict"; function boot() { var el = document.getElementById("cursor"); if (!el) return; var x = window.innerWidth / 2, y = window.innerHeight / 2; var tx = x, ty = y; var visible = false; function raf() { x += (tx - x) * 0.18; y += (ty - y) * 0.18; el.style.transform = "translate(" + (x - 9) + "px," + (y - 9) + "px)"; requestAnimationFrame(raf) } raf(); window.addEventListener("pointermove", function (e) { tx = e.clientX; ty = e.clientY; if (!visible) { visible = true; el.style.opacity = "1" } }, { passive: true }); window.addEventListener("pointerdown", function () { el.classList.add("down") }, { passive: true }); window.addEventListener("pointerup", function () { el.classList.remove("down") }, { passive: true }); window.addEventListener("blur", function () { visible = false; el.style.opacity = "0" }) } if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot, { once: true }); else boot() })();
